  "1. Какие данные собираются DomLY может собирать имя, номер телефона, адрес, город, координаты дома, данные заказов, оплат, сообщений, фотографий отчетов, жалоб, отзывов и техническую информацию приложения. 2. Для чего используются данные Данные нужны для регистрации, подтверждения адреса и площади, расчета стоимости, приема оплаты, назначения исполнителя, выполнения уборки, поддержки клиента, уведомлений и контроля качества. 3. Передача данных DomLY передает исполнителю только данные, необходимые для выполнения заказа: адрес, время, параметры уборки, чек-лист и контактные данные для связи по заказу. Данные оплаты обрабатываются платежными провайдерами. 4. Хранение и защита DomLY хранит данные в защищенной серверной инфраструктуре и применяет технические меры защиты доступа. Доступ к данным предоставляется только пользователю, исполнителю, администратору и сервисным ролям в рамках их задач. 5. Права пользователя Пользователь может запросить уточнение, исправление или удаление своих данных через поддержку DomLY, если хранение этих данных больше не требуется для исполнения обязательств и требований закона. 6. Реквизиты организации Наименование: ТОО \"DomLY\" БИН: 260440000313 Юридический адрес: Адрес уточняется Телефон: +7 777 040 9606 Email: milaniumkz@yandex.kz": "1. Қандай деректер жиналады\nDomLY пайдаланушының аты-жөнін, телефон нөмірін, мекенжайын, қаласын, үй координаттарын, тапсырыстар, төлемдер, хабарламалар, есеп фотосуреттері, шағымдар, пікірлер және қосымшаның техникалық ақпаратын жинауы мүмкін.\n\n2. Деректер не үшін пайдаланылады\nДеректер тіркелу, мекенжай мен ауданды растау, құнын есептеу, төлем қабылдау, орындаушыны тағайындау, тазалық қызметін орындау, клиентті қолдау, хабарламалар және сапаны бақылау үшін қажет.\n\n3. Деректерді беру\nDomLY орындаушыға тек тапсырысты орындауға қажетті деректерді береді: мекенжай, уақыт, тазалық параметрлері, чек-лист және тапсырыс бойынша байланыс деректері. Төлем деректерін төлем провайдерлері өңдейді.\n\n4. Сақтау және қорғау\nDomLY деректерді қорғалған серверлік инфрақұрылымда сақтайды және қолжетімділікті қорғаудың техникалық шараларын қолданады. Деректерге қолжетімділік пайдаланушыға, орындаушыға, әкімшіге және қызметтік рөлдерге олардың міндеттері шегінде беріледі.\n\n5. Пайдаланушы құқықтары\nПайдаланушы DomLY қолдау қызметі арқылы өз деректерін нақтылауды, түзетуді немесе жоюды сұрай алады, егер бұл деректерді сақтау міндеттемелерді орындау және заң талаптары үшін қажет болмаса.\n\n6. Ұйым реквизиттері\nАтауы: ТОО \"DomLY\"\nБСН: 260440000313\nЗаңды мекенжайы: Мекенжай нақтыланады\nТелефон: +7 777 040 9606\nEmail: milaniumkz@yandex.kz",
