еректерді DomLY серверінде сақтайды және қолжетімділікті қорғаудың техникалық шараларын қолданады. Деректерге пайдаланушы, орындаушы, әкімші және сервистік рөлдер өз міндеттері аясында ғана қол жеткізе алады.\n\n5. Пайдаланушы құқықтары\nПайдаланушы DomLY қолдау қызметі арқылы өз деректерін нақтылауды, түзетуді немесе жоюды сұрай алады, егер бұл деректерді сақтау міндеттемелерді орындау және заң талаптары үшін қажет болмаса.\n\n6. Ұйым реквизиттері\nАтауы: ТОО \"DomLY\"\nБСН: 260440000313\nЗаңды мекенжайы: Мекенжай нақтыланады\nТелефон: +7 778 111 0170\nEmail: milaniumkz@yandex.kz",
  "1. Модель работы": "1. Жұмыс үлгісі",
  "1. Модель работы DomLY принимает заявки клиента на уборку квартиры или дома, рассчитывает стоимость по выбранному пакету, площади и дополнительным услугам, принимает оплату и передает заказ исполнителю. Исполнитель выполняет уборку по чек-листу, клиент может общаться с исполнителем и поддержкой через приложение. 2. Оплата Клиент оплачивает пакет уборки или дополнительные услуги банковской картой через интернет-эквайринг либо через Kaspi.kz. Заказ считается подтвержденным после успешной оплаты или подтверждения счета. 3. Проверка площади Если площадь не подтверждена, DomLY может запросить проверку квадратуры отделом контроля качества. После подтверждения площади стоимость заказа может быть пересчитана. 4. Отмена и возврат Отмена и возврат рассматриваются администрацией DomLY по обращению клиента. Возврат выполняется тем же способом, которым была произведена оплата, если это поддерживается платежной системой. 5. Реквизиты организации Наименование: ТОО \"DomLY\" БИН: 260440000313 Юридический адрес: Адрес уточняется Банк: АО «Банк ЦентрКредит» ИИК: KZ11 8562 2031 5395 7207 БИК: KCJBKZKX КБе: 17 Валюта: KZT Телефон: +7 777 040 9606 Email: milaniumkz@yandex.kz": "1. Жұмыс моделі\nDomLY клиенттің пәтер немесе үй тазалау өтінімін қабылдайды, таңдалған пакет, аудан және қосымша қызметтер бойынша құнын есептейді, төлемді қабылдайды және тапсырысты орындаушыға береді. Орындаушы тазалықты чек-лист бойынша орындайды, клиент орындаушымен және қолдау қызметімен қосымша арқылы байланыса алады.\n\n2. Төлем\nКлиент тазалық пакетін немесе қосымша қызметтерді интернет-эквайринг арқылы банк картасымен немесе Kaspi.kz арқылы төлейді. Тапсырыс төлем сәтті өткеннен немесе шот расталғаннан кейін расталған болып саналады.\n\n3. Ауданды тексеру\nЕгер аудан расталмаған болса, DomLY сапаны бақылау бөлімі арқылы аудан тексерісін сұрата алады. Аудан расталғаннан кейін тапсырыс құны қайта есептелуі мүмкін.\n\n4. Бас тарту және қайтару\nБас тарту және қайтару клиенттің өтініші бойынша DomLY әкімшілігімен қаралады. Қайтару төлем жасалған тәсілмен орындалады, егер оны төлем жүйесі қолдаса.\n\n5. Ұйым реквизиттері\nАтауы: ТОО \"DomLY\"\nБСН: 260440000313\nЗаңды мекенжайы: Мекенжай нақтыланады\nБанк: «Банк ЦентрКредит» АҚ\nЖСК: KZ11 8562 2031 5395 7207\nБСК: KCJBKZKX\nКБе: 17\nВалюта: KZT\nТелефон: +7 777 040 9606\nEmail: milaniumkz@yandex.kz",
