  "<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>DomLY — BCC</title></head><body><p>Открываем страницу банка…</p><form id=\"bcc-payment\" method=\"{p0}\" action=\"{p1}\">{p2}<button type=\"submit\">Перейти к оплате</button></form><script>document.getElementById('bcc-payment').submit();</script></body></html>": "<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>DomLY - BCC</title></head><body><p>Банк бетін ашыңыз...</p><form id=\"bcc-payment\" method=\"bcc-payment\" әдісі{p0}\"әрекет\"{p1}«>{p2}<button type=\"submit\">Төлемге өту</button></form><script>document.getElementById('bcc-payment').submit();</script></body></html>",
  "><title>DomLY — BCC</title></head><body><p>Открываем страницу банка…</p><form id=": "><title>DomLY - BCC</title></head><body><p>Банк бетін ашыңыз...</p><form id=",
