  "CSV по чек-листам скопирован": "Тексеру парақтары үшін CSV көшірілді",
  "DomLY Админ-панель": "DomLY әкімші тақтасы",
  "DomLY деректерді қорғалған серверлік инфрақұрылымда сақтайды және қолжетімділікті қорғаудың техникалық шараларын қолданады. Деректерге қолжетімділік пайдаланушыға, орындаушыға, әкімшіге және қызметтік рөлдерге олардың міндеттері шегінде беріледі.": "DomLY деректерді қорғалған серверлік инфрақұрылымда сақтайды және қолжетімділікті қорғаудың техникалық шараларын қолданады. Деректерге қолжетімділік пайдаланушыға, орындаушыға, әкімшіге және қызметтік рөлдерге олардың міндеттері шегінде беріледі.",
  "DomLY жүйесіне кіру": "DomLY жүйесіне кіру",
  "DomLY запущен": "DomLY іске қосылды",
  "DomLY клиенттің пәтер немесе үй тазалау өтінімін қабылдайды, таңдалған пакет, аудан және қосымша қызметтер бойынша құнын есептейді, төлемді қабылдайды және тапсырысты орындаушыға береді. Орындаушы тазалықты чек-лист бойынша орындайды, клиент орындаушымен және қолдау қызметімен қосымша арқылы байланыса алады.": "DomLY клиенттің пәтер немесе үй тазалау өтінімін қабылдайды, таңдалған пакет, аудан және қосымша қызметтер бойынша құнын есептейді, төлемді қабылдайды және тапсырысты орындаушыға береді. Орындаушы тазалықты чек-лист бойынша орындайды, клиент орындаушымен және қолдау қызметімен қосымша арқылы байланыса алады.",
  "DomLY код подтверждения: {p0}": "DomLY растау коды: {p0}",
  "DomLY может собирать имя, номер телефона, адрес, город, координаты дома, данные заказов, оплат, сообщений, фотографий отчетов, жалоб, отзывов и техническую информацию приложения.": "DomLY атын, телефон нөмірін, мекенжайын, қаланы, үй координаттарын, тапсырыс деректерін, төлемдерді, хабарламаларды, фото есептерді, шағымдарды, шолуларды және техникалық қолданба туралы ақпаратты жинай алады.",
  "DomLY орындаушыға тек тапсырысты орындауға қажетті деректерді береді: мекенжай, уақыт, тазалық параметрлері, чек-лист және тапсырыс бойынша байланыс деректері. Төлем деректерін төлем провайдерлері өңдейді.": "DomLY орындаушыға тек тапсырысты орындауға қажетті деректерді береді: мекенжай, уақыт, тазалық параметрлері, чек-лист және тапсырыс бойынша байланыс деректері. Төлем деректерін төлем провайдерлері өңдейді.",
  "DomLY пайдаланушының аты-жөнін, телефон нөмірін, мекенжайын, қаласын, үй координаттарын, тапсырыстар, төлемдер, хабарламалар, есеп фотосуреттері, шағымдар, пікірлер және қосымшаның техникалық ақпаратын жинауы мүмкін.": "DomLY пайдаланушының аты-жөнін, телефон нөмірін, мекенжайын, қаласын, үй координаттарын, тапсырыстар, төлемдер, хабарламалар, есеп фотосуреттері, шағымдар, пікірлер және қосымшаның техникалық ақпаратын жинауы мүмкін.",
  "DomLY передает исполнителю только данные, необходимые для выполнения заказа: адрес, время, параметры уборки, чек-лист и контактные данные для связи по заказу. Данные оплаты обрабатываются платежными провайдерами.": "DomLY мердігерге тапсырысты орындау үшін қажетті деректерді ғана береді: мекенжай, уақыт, тазалау параметрлері, бақылау парағы және тапсырысқа қатысты байланыс үшін байланыс ақпараты. Төлем деректерін төлем провайдерлері өңдейді.",
  "DomLY принимает заявки клиента на уборку квартиры или дома, рассчитывает стоимость по выбранному пакету, площади и дополнительным услугам, принимает оплату и передает заказ исполнителю. Исполнитель выполняет уборку по чек-листу, клиент может общаться с исполнителем и поддержкой через приложение.": "DomLY пәтерді немесе үйді тазалау бойынша клиенттердің өтініштерін қабылдайды, таңдалған пакеттің, аумақтың және қосымша қызметтердің құнын есептейді, төлемді қабылдайды және тапсырысты мердігерге аударады. Мердігер тазалауды бақылау парағына сәйкес жүзеге асырады, клиент мердігермен байланысып, қосымша арқылы қолдау көрсете алады.",
  "DomLY принимает оплату за пакеты уборки и дополнительные услуги банковской картой через интернет-эквайринг и через Kaspi.kz.": "DomLY интернет-эквайринг және Kaspi.kz арқылы банк картасымен тазалау пакеттері мен қосымша қызметтер үшін төлемді қабылдайды.",
  "DomLY хранит данные в защищенной серверной инфраструктуре и применяет технические меры защиты доступа. Доступ к данным предоставляется только пользователю, исполнителю, администратору и сервисным ролям в рамках их задач.": "DomLY қауіпсіз сервер инфрақұрылымында деректерді сақтайды және қол жеткізуді қорғаудың техникалық шараларын қолданады. Деректерге қол жеткізу тек пайдаланушыға, орындаушыға, әкімші және қызмет рөлдеріне олардың тапсырмалары аясында беріледі.",
