  "Moon AI отправляет только status, amount, phone, dateTime; ID не нужен. Единственное совпадение телефона/суммы/времени обрабатывается автоматически, неоднозначное — вручную. Статусы invoice_sent, paid, rejected, cancelled. Защита: Authorization: Bearer <MOON_AI_WEBHOOK_TOKEN> или X-MoonAI-Token.": "Moon AI тек күйді, соманы, телефонды, dateTime жібереді; Идентификатор қажет емес. Бір телефон/сома/уақыт сәйкестігі автоматты түрде өңделеді, анық еместері қолмен өңделеді. Invoice_sent, төленген, қабылданбаған, жойылған күйлері. Қауіпсіздік: Авторизация: Тасымалдаушы <MOON_AI_WEBHOOK_TOKEN> немесе X-MoonAI-Токен.",
