  "Других платежей по текущему фильтру нет.": "Ағымдағы сүзгі үшін басқа төлемдер жоқ.",
  "Егер аудан расталмаған болса, DomLY сапаны бақылау бөлімі арқылы аудан тексерісін сұрата алады. Аудан расталғаннан кейін тапсырыс құны қайта есептелуі мүмкін.": "Егер аудан расталмаған болса, DomLY сапаны бақылау бөлімі арқылы аудан тексерісін сұрата алады. Аудан расталғаннан кейін тапсырыс құны қайта есептелуі мүмкін.",
  "Еженедельные бонусы становятся доступны к выводу через 7 календарных дней.": "Апталық бонустар 7 күнтізбелік күннен кейін алуға болады.",
