  "Если включено, после оплаты пакета клиенту начислятся бонусы.": "Қосылған болса, пакетті төлегеннен кейін клиент бонустар алады.",
  "Если вы подтвердите площадь документом, после проверки администратором будет начислен бонус. Эту площадь мы будем использовать при оформлении заказов.": "Егер сіз аумақты құжатпен растасаңыз, әкімші тексергеннен кейін бонус беріледі. Тапсырыс бергенде осы аумақты қолданамыз.",
  "Если оценка ниже 3 звезд, отметьте причины.": "Егер рейтинг 3 жұлдыздан төмен болса, себептерін ескеріңіз.",
  "Если передумали или ошиблись со временем, отмените уборку. Она вернется в доступные, и можно будет выбрать новую дату.": "Егер сіз ойыңызды өзгертсеңіз немесе уақыт бойынша қателессеңіз, тазалаудан бас тартыңыз. Ол қолжетімділерге оралады және сіз жаңа күнді таңдай аласыз.",
  "Если площадь не подтверждена, DomLY может запросить проверку квадратуры отделом контроля качества. После подтверждения площади стоимость заказа может быть пересчитана.": "Егер аймақ расталмаса, DomLY сапаны бақылау бөлімінен аумақты тексеруді сұрауы мүмкін. Ауданды растағаннан кейін тапсырыс құнын қайта есептеуге болады.",
  "Если потребуется уточнение, менеджер свяжется с вами отдельно.": "Түсіндіру қажет болса, менеджер сізбен бөлек хабарласады.",
