  "Не удалось изменить уборку": "Тазалауды өзгерту мүмкін болмады",
  "Не удалось назначить уборщицу. Проверьте статус заказа, район, город, занятость уборщицы и попробуйте снова.": "Тазалаушы әйел тағайындалмады. Тапсырыс күйін, аймақты, қаланы, тазартқыштың қолжетімділігін тексеріп, әрекетті қайталаңыз.",
  "Не удалось назначить: визит уборки не найден. Обновите страницу заказов, проверьте, что заказ не отменен, и попробуйте снова.": "Жоспар орындалмады: тазалау кездесуі табылмады. Тапсырыстар бетін жаңартып, тапсырыстың жойылмағанын тексеріп, әрекетті қайталаңыз.",
  "Не удалось назначить: заказ вне рабочих районов уборщицы. Добавьте ей нужный район или выберите другую уборщицу.": "Тағайындау орындалмады: тазалаушы әйелдің жұмыс аймағынан тыс жерде тапсырыс беріңіз. Оған қажет аймақты қосыңыз немесе басқа тазалағышты таңдаңыз.",
  "Не удалось назначить: заказ не в ожидании назначения. Верните заказ в статус ожидания назначения или создайте новый подбор уборщицы.": "Тағайындау сәтсіз аяқталды: тапсырыс тапсырманы күтпейді. Тапсырысты күтудегі кездесу күйіне қайтарыңыз немесе тазартқыштардың жаңа таңдауын жасаңыз.",
  "Не удалось назначить: заказ не найден. Обновите страницу заказов.": "Тағайындау орындалмады: тапсырыс табылмады. Тапсырыстар бетін жаңартыңыз.",
  "Не удалось назначить: сессия администратора истекла. Войдите в админку заново.": "Тағайындау сәтсіз аяқталды: әкімші сеансының мерзімі аяқталды. Әкімші аймағына қайта кіріңіз.",
  "Не удалось назначить: у аккаунта нет прав администратора.": "Тағайындау сәтсіз аяқталды: тіркелгіде әкімші құқықтары жоқ.",
  "Не удалось назначить: уборщица из другого города. Выберите уборщицу из города клиента.": "Тағайындау орындалмады: басқа қаладан келген тазалықшы әйел. Клиенттің қаласынан тазалаушыны таңдаңыз.",
  "Не удалось назначить: уборщица не найдена в базе. Обновите список уборщиц.": "Тағайындау сәтсіз аяқталды: тазартқыш дерекқордан табылмады. Тазалау қызметкерлерінің тізімін жаңартыңыз.",
  "Не удалось назначить: уборщица не подтверждена. Откройте карточку уборщицы и подтвердите ее.": "Тағайындау сәтсіз аяқталды: тазартқыш расталмады. Тазартқыш картасын ашып, оны растаңыз.",
  "Не удалось назначить: функция временно недоступна. Проверьте интернет и попробуйте еще раз.": "Тағайындау сәтсіз аяқталды: мүмкіндік уақытша қолжетімсіз. Интернетті тексеріп, әрекетті қайталаңыз.",
