  "Перед уборкой нужно подтвердить площадь квартиры. Пришлите в этот WhatsApp-чат чёткий технический план с адресом и общей площадью квартиры. Либо откройте мобильное приложение DomLY → Профиль → Подтвердить площадь → Фото технического плана, прикрепите чёткий снимок и нажмите «Подтвердить площадь». Если не хотите отправлять документ, напишите — согласуем дату и время проверки отделом качества до уборки.": "Тазалау алдында пәтердің аумағын растау керек. Осы WhatsApp чатына пәтердің мекен-жайы мен жалпы ауданы көрсетілген нақты техникалық жоспарды жіберіңіз. Немесе DomLY мобильді қосымшасын → Профиль → Растау аймағы → Техникалық жоспардың фотосуретін ашып, анық фотосуретті тіркеп, «Аймақты растау» түймесін басыңыз. Құжатты жібергіңіз келмесе, жазыңыз, біз тазалау алдында сапа бөлімімен тексеру күні мен уақытын келісеміз.",
  "Передайте active: true или false.": "Белсенді өту: шын немесе жалған.",
